-- =====================================================================
-- Proyecto Final BD II - Oracle (implementación parcial)
-- 01 - DDL del subconjunto: región, ciudad, hub, servicio, tarifa,
--      cliente, envío y evento de tracking (8 tablas)
-- Motor: Oracle AI Database 26ai Free (23.26) | Esquema: OLVA | PDB: FREEPDB1
-- =====================================================================
-- Diferencias de DDL respecto a PostgreSQL (ver comentarios "[ORA]"):
--   * VARCHAR2 / NUMBER en lugar de VARCHAR / INTEGER / NUMERIC
--   * IDENTITY "BY DEFAULT ON NULL" (PG: GENERATED BY DEFAULT AS IDENTITY)
--   * REGEXP_LIKE() en CHECK (PG: operador ~)
--   * No hay schemas independientes del usuario: el esquema ES el usuario OLVA
--   * DROP TABLE IF EXISTS existe recién desde 23ai (antes: bloque PL/SQL con EXCEPTION)
--   * BOOLEAN como tipo SQL existe recién desde 23ai (antes: NUMBER(1) o CHAR(1))
-- =====================================================================
SET ECHO ON
SET DEFINE OFF

DROP TABLE IF EXISTS evento_tracking CASCADE CONSTRAINTS PURGE;
DROP TABLE IF EXISTS envio           CASCADE CONSTRAINTS PURGE;
DROP TABLE IF EXISTS cliente         CASCADE CONSTRAINTS PURGE;
DROP TABLE IF EXISTS tarifa          CASCADE CONSTRAINTS PURGE;
DROP TABLE IF EXISTS tipo_servicio   CASCADE CONSTRAINTS PURGE;
DROP TABLE IF EXISTS hub             CASCADE CONSTRAINTS PURGE;
DROP TABLE IF EXISTS ciudad          CASCADE CONSTRAINTS PURGE;
DROP TABLE IF EXISTS region          CASCADE CONSTRAINTS PURGE;
DROP TABLE IF EXISTS log_error       CASCADE CONSTRAINTS PURGE;

CREATE TABLE region (
    id_region  NUMBER(3)     CONSTRAINT pk_region PRIMARY KEY,
    codigo     VARCHAR2(5)   NOT NULL CONSTRAINT uq_region_codigo UNIQUE,
    nombre     VARCHAR2(40)  NOT NULL CONSTRAINT uq_region_nombre UNIQUE,
    nodo       VARCHAR2(10)  NOT NULL CONSTRAINT ck_region_nodo CHECK (nodo IN ('LIMA', 'NORTE', 'SUR'))
);

CREATE TABLE ciudad (
    id_ciudad         NUMBER(6)    GENERATED BY DEFAULT ON NULL AS IDENTITY CONSTRAINT pk_ciudad PRIMARY KEY,
    nombre            VARCHAR2(60) NOT NULL,
    departamento      VARCHAR2(40) NOT NULL,
    id_region         NUMBER(3)    NOT NULL CONSTRAINT fk_ciudad_region REFERENCES region (id_region),
    ubigeo            CHAR(6)      NOT NULL CONSTRAINT uq_ciudad_ubigeo UNIQUE
                                   CONSTRAINT ck_ciudad_ubigeo CHECK (REGEXP_LIKE(ubigeo, '^[0-9]{6}$')),
    tiene_aeropuerto  BOOLEAN      DEFAULT FALSE NOT NULL,       -- [ORA] BOOLEAN SQL nativo desde 23ai
    acceso_terrestre  BOOLEAN      DEFAULT TRUE  NOT NULL,
    latitud           NUMBER(9,6),
    longitud          NUMBER(9,6),
    CONSTRAINT uq_ciudad UNIQUE (nombre, departamento),
    CONSTRAINT ck_ciudad_accesible CHECK (tiene_aeropuerto OR acceso_terrestre)
);

CREATE TABLE hub (
    id_hub          NUMBER(6)     GENERATED BY DEFAULT ON NULL AS IDENTITY CONSTRAINT pk_hub PRIMARY KEY,
    codigo          VARCHAR2(12)  NOT NULL CONSTRAINT uq_hub_codigo UNIQUE,
    nombre          VARCHAR2(80)  NOT NULL,
    tipo            VARCHAR2(15)  NOT NULL CONSTRAINT ck_hub_tipo CHECK (tipo IN ('HUB_CENTRAL', 'HUB_REGIONAL', 'AGENCIA')),
    id_ciudad       NUMBER(6)     NOT NULL CONSTRAINT fk_hub_ciudad REFERENCES ciudad (id_ciudad),
    id_hub_padre    NUMBER(6)     CONSTRAINT fk_hub_padre REFERENCES hub (id_hub),
    capacidad_hora  NUMBER(6)     NOT NULL CONSTRAINT ck_hub_capacidad CHECK (capacidad_hora > 0),
    activo          BOOLEAN       DEFAULT TRUE NOT NULL,
    CONSTRAINT ck_hub_jerarquia CHECK ((tipo = 'HUB_CENTRAL' AND id_hub_padre IS NULL) OR
                                       (tipo <> 'HUB_CENTRAL' AND id_hub_padre IS NOT NULL))
);

CREATE TABLE tipo_servicio (
    id_servicio  NUMBER(3)     CONSTRAINT pk_tipo_servicio PRIMARY KEY,
    codigo       VARCHAR2(20)  NOT NULL CONSTRAINT uq_servicio_codigo UNIQUE,
    nombre       VARCHAR2(60)  NOT NULL,
    modalidad    VARCHAR2(10)  NOT NULL CONSTRAINT ck_servicio_modalidad CHECK (modalidad IN ('AEREO', 'TERRESTRE')),
    sla_horas    NUMBER(4)     NOT NULL CONSTRAINT ck_servicio_sla CHECK (sla_horas BETWEEN 1 AND 720),
    peso_max_kg  NUMBER(6,2)   NOT NULL CONSTRAINT ck_servicio_peso CHECK (peso_max_kg > 0)
);

CREATE TABLE tarifa (
    id_tarifa            NUMBER(8)    GENERATED BY DEFAULT ON NULL AS IDENTITY CONSTRAINT pk_tarifa PRIMARY KEY,
    id_servicio          NUMBER(3)    NOT NULL CONSTRAINT fk_tarifa_servicio REFERENCES tipo_servicio (id_servicio),
    id_region_origen     NUMBER(3)    NOT NULL CONSTRAINT fk_tarifa_reg_origen REFERENCES region (id_region),
    id_region_destino    NUMBER(3)    NOT NULL CONSTRAINT fk_tarifa_reg_destino REFERENCES region (id_region),
    precio_base          NUMBER(8,2)  NOT NULL CONSTRAINT ck_tarifa_base CHECK (precio_base >= 0),
    precio_kg_adicional  NUMBER(8,2)  NOT NULL CONSTRAINT ck_tarifa_kg CHECK (precio_kg_adicional >= 0),
    vigente_desde        DATE         NOT NULL,
    vigente_hasta        DATE,
    CONSTRAINT uq_tarifa UNIQUE (id_servicio, id_region_origen, id_region_destino, vigente_desde),
    CONSTRAINT ck_tarifa_vigencia CHECK (vigente_hasta IS NULL OR vigente_hasta > vigente_desde)
);

CREATE TABLE cliente (
    id_cliente           NUMBER(10)     GENERATED BY DEFAULT ON NULL AS IDENTITY CONSTRAINT pk_cliente PRIMARY KEY,
    tipo_cliente         VARCHAR2(8)    NOT NULL CONSTRAINT ck_cliente_tipo CHECK (tipo_cliente IN ('PERSONA', 'EMPRESA')),
    tipo_documento       VARCHAR2(3)    NOT NULL CONSTRAINT ck_cliente_tipodoc CHECK (tipo_documento IN ('DNI', 'RUC', 'CE')),
    nro_documento        VARCHAR2(12)   NOT NULL,
    nombre_razon_social  VARCHAR2(120)  NOT NULL,
    email                VARCHAR2(120)  CONSTRAINT ck_cliente_email
                                        CHECK (REGEXP_LIKE(email, '^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$', 'i')),
    telefono             VARCHAR2(15),
    id_ciudad            NUMBER(6)      NOT NULL CONSTRAINT fk_cliente_ciudad REFERENCES ciudad (id_ciudad),
    fecha_registro       DATE           DEFAULT SYSDATE NOT NULL,
    CONSTRAINT uq_cliente_documento UNIQUE (tipo_documento, nro_documento),
    CONSTRAINT ck_cliente_documento CHECK (
        (tipo_documento = 'DNI' AND REGEXP_LIKE(nro_documento, '^[0-9]{8}$')) OR
        (tipo_documento = 'RUC' AND REGEXP_LIKE(nro_documento, '^(10|20)[0-9]{9}$')) OR
        (tipo_documento = 'CE'  AND REGEXP_LIKE(nro_documento, '^[0-9]{9,12}$')))
);

CREATE TABLE envio (
    id_envio          NUMBER(12)    GENERATED BY DEFAULT ON NULL AS IDENTITY CONSTRAINT pk_envio PRIMARY KEY,
    nro_tracking      CHAR(13)      NOT NULL CONSTRAINT uq_envio_tracking UNIQUE
                                    CONSTRAINT ck_envio_tracking CHECK (REGEXP_LIKE(nro_tracking, '^OLV[0-9]{10}$')),
    id_cliente        NUMBER(10)    NOT NULL CONSTRAINT fk_envio_cliente REFERENCES cliente (id_cliente),
    id_servicio       NUMBER(3)     NOT NULL CONSTRAINT fk_envio_servicio REFERENCES tipo_servicio (id_servicio),
    id_hub_origen     NUMBER(6)     NOT NULL CONSTRAINT fk_envio_hub_origen REFERENCES hub (id_hub),
    id_hub_destino    NUMBER(6)     NOT NULL CONSTRAINT fk_envio_hub_destino REFERENCES hub (id_hub),
    fecha_registro    TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    fecha_compromiso  TIMESTAMP WITH TIME ZONE NOT NULL,
    estado_actual     VARCHAR2(15)  DEFAULT 'REGISTRADO' NOT NULL
                      CONSTRAINT ck_envio_estado CHECK (estado_actual IN ('REGISTRADO', 'ADMITIDO', 'EN_HUB', 'EN_TRANSITO',
                                                        'EN_REPARTO', 'INTENTO_FALLIDO', 'ENTREGADO', 'DEVUELTO')),
    peso_total_kg     NUMBER(7,2)   NOT NULL CONSTRAINT ck_envio_peso CHECK (peso_total_kg > 0),
    monto_total       NUMBER(10,2)  NOT NULL CONSTRAINT ck_envio_monto CHECK (monto_total >= 0),
    fecha_entrega     TIMESTAMP WITH TIME ZONE,
    CONSTRAINT ck_envio_hubs       CHECK (id_hub_origen <> id_hub_destino),
    CONSTRAINT ck_envio_compromiso CHECK (fecha_compromiso > fecha_registro),
    CONSTRAINT ck_envio_entregado  CHECK ((estado_actual = 'ENTREGADO' AND fecha_entrega IS NOT NULL) OR
                                          (estado_actual <> 'ENTREGADO' AND fecha_entrega IS NULL))
);

CREATE TABLE evento_tracking (
    id_evento    NUMBER(14)     GENERATED BY DEFAULT ON NULL AS IDENTITY CONSTRAINT pk_evento PRIMARY KEY,
    id_envio     NUMBER(12)     NOT NULL CONSTRAINT fk_evento_envio REFERENCES envio (id_envio),
    tipo_evento  VARCHAR2(16)   NOT NULL CONSTRAINT ck_evento_tipo CHECK (tipo_evento IN ('ADMISION', 'SALIDA_HUB',
                                'LLEGADA_HUB', 'CLASIFICACION', 'EN_REPARTO', 'INTENTO_FALLIDO', 'ENTREGA', 'DEVOLUCION')),
    id_hub       NUMBER(6)      NOT NULL CONSTRAINT fk_evento_hub REFERENCES hub (id_hub),
    fecha_hora   TIMESTAMP WITH TIME ZONE NOT NULL,
    observacion  VARCHAR2(200)
);

-- Bitácora de errores escrita con transacción autónoma (ver 03_plsql.sql)
CREATE TABLE log_error (
    id_log      NUMBER GENERATED ALWAYS AS IDENTITY CONSTRAINT pk_log_error PRIMARY KEY,
    fecha       TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    usuario     VARCHAR2(128) DEFAULT SYS_CONTEXT('USERENV', 'SESSION_USER') NOT NULL,
    origen      VARCHAR2(60)  NOT NULL,
    mensaje     VARCHAR2(4000)
);

CREATE INDEX ix_ciudad_region      ON ciudad (id_region);
CREATE INDEX ix_hub_padre          ON hub (id_hub_padre);
CREATE INDEX ix_envio_cliente      ON envio (id_cliente);
CREATE INDEX ix_envio_origen_fecha ON envio (id_hub_origen, fecha_registro);
CREATE INDEX ix_evento_envio_fecha ON evento_tracking (id_envio, fecha_hora);
CREATE INDEX ix_evento_hub_fecha   ON evento_tracking (id_hub, fecha_hora);

COMMENT ON TABLE envio IS 'Envío (subconjunto del modelo PostgreSQL olva_courier.operacion.envio)';
COMMENT ON TABLE evento_tracking IS 'Escaneos de trazabilidad del envío';

SELECT table_name, num_rows FROM user_tables ORDER BY table_name;
